mapper.update:
UPDATE CHAT_ROOM
SET
ROOM_NAME=#{roomName},
ROOM_TYPE=#{roomType},
ROOM_DESCRIPTION=#{roomDescription}, MAX_MEMBER=#{maxMember}, IS_DEFAULT=#{isDefault}
WHERE ROOM_ID=#{roomId}

UPDATE CHAT_ROOM

SET STATUS='INACTIVE'

WHERE ROOM_ID=#{roomId}

mapper.delete:
DELETE

FROM CHAT_ROOM_MEMBER

WHERE ROOM_ID=#{roomId}

AND BUSINESS_NO=#{businessNo}

